if (*FUZZ_PARAM(unsigned int) & 1) {
    const Tld_table *tmp_overrides[1] = { 0 };
    ov0 = tld_default_table(tldname.c_str(), tmp_overrides);
}
const Tld_table *overrides_arr[2] = { ov0, 0 };

size_t errpos_val = 0; size_t *errpos = (*FUZZ_PARAM(unsigned int) & 2) ? &errpos_val : (size_t*)0;
int rc = tld_check_lz(dom.c_str(), errpos, overrides_arr);
(void)rc; (void)errpos_val;

// Generate a valid Pr29_rc value and call pr29_strerror.
// rc must be from Pr29_rc; we map a fuzzed integer into the enum domain [0..2].
unsigned int rcu = *FUZZ_PARAM(unsigned int) % 3; // 0: SUCCESS, 1: PROBLEM, 2: STRINGPREP_ERROR
Pr29_rc rc = static_cast<Pr29_rc>(rcu);
// Invoke target; returned pointer is to a static read-only string.
const char *msg = pr29_strerror(rc);
// Validate basic contract: returned pointer should be non-null and point to a NUL-terminated string.
FUZZ_ASSERT(msg != nullptr, "pr29_strerror returned null");
// Touch a few bytes to encourage coverage without modifying.
(volatile char)msg[0];
// Note: no ownership transfer; do not free or modify.
// Validation: rc constrained to enum range; output treated as static and read-only.

// Build a UCS-4 buffer from fuzz bytes, enforcing buffer/len constraints.
std::string blob = FUZZ_PARAM_STR();
// Derive a reasonable code point count <= 256 and <= blob.size()/4.
size_t cp_budget = blob.size() / 4; // each code point uses 4 bytes from blob
if (cp_budget > 256) cp_budget = 256;
// Allow empty input (len==0) as a valid case.
size_t len = cp_budget ? ((size_t)*FUZZ_PARAM(unsigned int) % (cp_budget + 1)) : 0;
// Allocate at least one element so the pointer is non-null even when len==0.
std::vector<uint32_t> ucs4(len ? len : 1u);
// Populate len code points by packing 4 bytes each, mapping to valid Unicode scalars.
for (size_t i = 0; i < len; i++) {
    const size_t off = (i * 4) % blob.size();
    uint32_t v = ((uint32_t)(unsigned char)blob[off]) |
                 ((uint32_t)(unsigned char)blob[(off + 1) % blob.size()] << 8) |
                 ((uint32_t)(unsigned char)blob[(off + 2) % blob.size()] << 16) |
                 ((uint32_t)(unsigned char)blob[(off + 3) % blob.size()] << 24);
    v = v % 0x110000u; // map to 0..0x10FFFF
    // Avoid surrogate range 0xD800-0xDFFF; map into BMP letter 'A' if so.
    if (v >= 0xD800u && v <= 0xDFFFu) v = 0x41u;
    ucs4[i] = v;
}
// Call the target. Pointer is non-null; len is element count (code points).
int rc = pr29_4(ucs4.data(), len);
// Touch rc to avoid optimizing away; API allows PR29_SUCCESS/PR29_PROBLEM or others.
(volatile int)rc;
// Validation: input buffer sized to >=len; values mapped to valid Unicode scalars; function is non-mutating.

// Build a NUL-terminated UCS-4 buffer from fuzz bytes.
std::string blob = FUZZ_PARAM_STR();
size_t cp_budget = blob.size() / 4; // available code points from fuzz blob
if (cp_budget > 128) cp_budget = 128; // cap to keep allocations small
// Choose a length in [0..cp_budget].
size_t n = cp_budget ? ((size_t)*FUZZ_PARAM(unsigned int) % (cp_budget + 1)) : 0;
// Allocate n code points plus the NUL terminator.
std::vector<uint32_t> ucs4(n + 1u);
for (size_t i = 0; i < n; i++) {
    const size_t off = (i * 4) % blob.size();
    uint32_t v = ((uint32_t)(unsigned char)blob[off]) |
                 ((uint32_t)(unsigned char)blob[(off + 1) % blob.size()] << 8) |
                 ((uint32_t)(unsigned char)blob[(off + 2) % blob.size()] << 16) |
                 ((uint32_t)(unsigned char)blob[(off + 3) % blob.size()] << 24);
    v = v % 0x110000u; // 0..0x10FFFF
    if (v >= 0xD800u && v <= 0xDFFFu) v = 0x20u; // avoid surrogates; map to space
    ucs4[i] = v;
}
ucs4[n] = 0; // required NUL terminator
// Invoke target with a non-null, NUL-terminated array.
int rc = pr29_4z(ucs4.data());
(volatile int)rc;
// Validation: ensures non-null pointer, proper NUL-termination, and valid scalar values for non-terminal elements.

// Generate a NUL-terminated 8-bit string. May be invalid UTF-8, which is acceptable.
std::string s = FUZZ_PARAM_STR();
// Optionally shrink to keep it small.
size_t max_len = 256;
if (s.size() > max_len) s.resize(max_len);
// Call target using NUL-terminated c_str().
const char *c = s.c_str();
FUZZ_ASSERT(c != nullptr, "c_str returned null");
int rc = pr29_8z(c);
(volatile int)rc;
// Validation: input is non-null, NUL-terminated; errors like PR29_STRINGPREP_ERROR are permissible by API.

