import random
import string
from typing import List

# Generator for version-like strings to exercise stringprep_check_version.
# We produce a variety of formats: semantic versions, prerelease/build metadata,
# legacy formats, edge cases (empty, long segments), and unusual but valid ASCII.

MAX_TOTAL_LEN = 4096

SEMVER_PRE_IDS = [
    "alpha", "beta", "rc", "dev", "snapshot", "exp", "preview",
]
BUILD_META_IDS = [
    "build", "exp", "jenkins", "git", "sha", "meta", "win", "linux", "x86_64",
]

LEGACY_PREFIXES = ["v", "V", "release-", "r", "R", "ver-", "", "version-"]
SUFFIXES = ["", "a", "b", "rc", "pre", "p", "pl", "u", "-stable", "-LTS", "-ESR"]
DATE_SEPARATORS = ["", ".", "-", "_"]


def _randint(rng: random.Random, a: int, b: int) -> int:
    return rng.randint(a, b)


def _random_numeric_id(rng: random.Random, max_digits: int = 6) -> str:
    digits = _randint(rng, 1, max_digits)
    # Occasionally include leading zeros to test lexicographic vs numeric compare
    if rng.random() < 0.3:
        return ("0" * _randint(rng, 1, 2)) + str(_randint(rng, 0, 10 ** max_digits - 1))
    return str(_randint(rng, 0, 10 ** digits - 1))


def _random_ident(rng: random.Random, min_len: int = 1, max_len: int = 8) -> str:
    chars = string.ascii_letters + string.digits + "-"
    n = _randint(rng, min_len, max_len)
    return ''.join(rng.choice(chars) for _ in range(n))


def _make_semver(rng: random.Random) -> str:
    major = _randint(rng, 0, 100)
    minor = _randint(rng, 0, 100)
    patch = _randint(rng, 0, 100)
    base = f"{major}.{minor}.{patch}"

    # Optionally add prerelease identifiers
    if rng.random() < 0.6:
        count = _randint(rng, 1, 3)
        ids: List[str] = []
        for _ in range(count):
            if rng.random() < 0.6:
                ids.append(rng.choice(SEMVER_PRE_IDS))
            else:
                ids.append(_random_ident(rng))
        # sometimes include numeric
        if rng.random() < 0.7:
            ids.append(_random_numeric_id(rng))
        base += "-" + ".".join(ids)

    # Optionally add build metadata
    if rng.random() < 0.5:
        count = _randint(rng, 1, 3)
        ids = []
        for _ in range(count):
            if rng.random() < 0.6:
                ids.append(rng.choice(BUILD_META_IDS))
            else:
                ids.append(_random_ident(rng))
        base += "+" + ".".join(ids)

    # Optional legacy prefix like v1.2.3
    if rng.random() < 0.5:
        base = rng.choice(LEGACY_PREFIXES) + base
    return base


def _make_legacy(rng: random.Random) -> str:
    # Legacy style like 1.2, 1.2a, 2.0rc1, 2020.04, 3.10.0-123.el7
    parts = [_random_numeric_id(rng, max_digits=3)]
    if rng.random() < 0.9:
        parts.append(_random_numeric_id(rng, max_digits=3))
    if rng.random() < 0.7:
        parts.append(_random_numeric_id(rng, max_digits=3))
    base = ".".join(parts)

    # Optional distro-style suffix
    if rng.random() < 0.5:
        base += f"-{_random_ident(rng, 1, 6)}{_randint(rng, 0, 999)}"

    # Optional trailing classic suffix
    if rng.random() < 0.6:
        base += rng.choice(SUFFIXES)

    # Optional prefix
    if rng.random() < 0.4:
        base = rng.choice(LEGACY_PREFIXES) + base
    return base


def _make_date_version(rng: random.Random) -> str:
    # Date-like: 2020.04.01, 20200401, 2021-09, 20210915.1
    year = _randint(rng, 1990, 2099)
    month = _randint(rng, 1, 12)
    day = _randint(rng, 1, 28)
    sep = rng.choice(DATE_SEPARATORS)
    if rng.random() < 0.5:
        base = f"{year}{sep}{month:02d}"
        if rng.random() < 0.8:
            base += f"{sep}{day:02d}"
    else:
        base = f"{year}{month:02d}{day:02d}"
    if rng.random() < 0.4:
        base += "." + _random_numeric_id(rng, 3)
    return base


def _make_weird_but_valid(rng: random.Random) -> str:
    # Include whitespace, underscores, very long numeric segments, and dots at edges
    choices = [
        "" ,
        "0", "00.0", "01.002.0003",
        "..", ".1.2.",
        "_", "1_2_3", "v_1.2",
        "1.2.3.4.5.6.7.8",
        "v" + "9" * _randint(rng, 1, 20) + ".0",
        "1." + "0" * _randint(rng, 1, 15),
    ]
    base = rng.choice(choices)
    # Occasionally append a build-like tail to odd bases
    if rng.random() < 0.3 and base:
        base += "+" + _random_ident(rng, 1, 6)
    return base


def _clip(b: bytes) -> bytes:
    if len(b) > MAX_TOTAL_LEN:
        return b[:MAX_TOTAL_LEN]
    return b


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a strategy for version string generation
    strategy = rng.choices(
        population=["semver", "legacy", "date", "weird", "mix"],
        weights=[40, 25, 15, 10, 10],
        k=1,
    )[0]

    versions: List[str] = []

    if strategy == "semver":
        versions.append(_make_semver(rng))
    elif strategy == "legacy":
        versions.append(_make_legacy(rng))
    elif strategy == "date":
        versions.append(_make_date_version(rng))
    elif strategy == "weird":
        versions.append(_make_weird_but_valid(rng))
    else:  # mix: concatenate multiple with separators to explore parsing
        count = _randint(rng, 2, 4)
        makers = [_make_semver, _make_legacy, _make_date_version, _make_weird_but_valid]
        sep_choices = [" ", ",", ";", " | ", "/", "_"]
        parts = []
        for _ in range(count):
            parts.append(rng.choice(makers)(rng))
        versions.append((rng.choice(sep_choices)).join(parts))

    # Optionally pad with surrounding text to simulate real-world version banners
    if rng.random() < 0.25:
        prefix = rng.choice(["", "libidn-", "stringprep-", "GNU libidn "])
        suffix = rng.choice(["", " (stable)", " (beta)", "-dev", "-unknown"]) 
        versions[0] = prefix + versions[0] + suffix

    data = versions[0].encode("utf-8", errors="strict") + b"\x00"
    return _clip(data)

import random

# Generator for encoding names and sample strings suitable for stringprep_convert fuzzers.
# We produce a single bytes blob that the harness splits for FUZZ_PARAM_STR etc.
# Ensure the source code contains no literal NUL characters; construct them at runtime.

COMMON_ENCODINGS = [
    "UTF-8", "utf8", "UTF8",
    "US-ASCII", "ASCII",
    "ISO-8859-1", "ISO8859-1", "latin1", "LATIN1",
    "UTF-16LE", "UTF-16BE", "UTF-16",
]

# Sample Unicode texts (as Python str)
SAMPLES_TEXT = [
    "",  # empty
    "hello",
    "example",
    "café",
    "Grüße",
    "©®µ",  # Latin-1 range
    "Привет",
    "नमस्कार",
    "日本語",
    "测试",
    "السلام",
    "xn--caf-dma",  # punycode-looking ASCII
    "foo.bar-baz",
]


def variants(enc: str):
    outs = {enc, enc.lower(), enc.upper()}
    parts = enc.replace('_', '-').split('-')
    outs.add('-'.join(p.capitalize() for p in parts))
    return list(outs)


def make_null_terminated(b: bytes) -> bytes:
    return b + b"\x00"


def encode_payload(text: str, enc_from: str) -> bytes:
    enc = enc_from.lower()
    try:
        if enc in ("utf-16",):
            # Python's 'utf-16' emits BOM
            return text.encode("utf-16")
        elif enc in ("utf-16le", "utf-16-be", "utf-16be"):
            norm = enc.replace('-be', 'be').replace('-le', 'le')
            if norm == "utf-16le":
                return text.encode("utf-16le")
            else:
                return text.encode("utf-16be")
        elif enc in ("us-ascii", "ascii"):
            ascii_text = text.encode('ascii', errors='ignore').decode('ascii')
            return ascii_text.encode('ascii')
        elif enc in ("iso-8859-1", "iso8859-1", "latin1", "latin-1"):
            return text.encode('latin-1', errors='ignore')
        elif enc in ("utf8", "utf-8"):
            return text.encode('utf-8')
        else:
            return text.encode(enc_from)
    except Exception:
        return text.encode('utf-8', errors='ignore')


def pick_encodings(rng: random.Random):
    base = rng.choice(COMMON_ENCODINGS)
    enc_from = rng.choice(variants(base))
    base2 = rng.choice(COMMON_ENCODINGS)
    enc_to = rng.choice(variants(base2))
    return enc_from, enc_to


def build_blob(rng: random.Random) -> bytes:
    pieces = []

    # Encoding names pool
    enc_names = []
    for _ in range(rng.randint(3, 8)):
        f, t = pick_encodings(rng)
        enc_names.extend([f, t])
    seen = set()
    enc_names_unique = []
    for e in enc_names:
        key = e.lower()
        if key not in seen:
            seen.add(key)
            enc_names_unique.append(e)

    for name in enc_names_unique[:16]:
        pieces.append(make_null_terminated(name.encode('ascii', errors='ignore')))

    for name in ["UTF-8", "ISO-8859-1", "US-ASCII", "UTF-16LE", "UTF-16BE", "UTF-16"]:
        pieces.append(make_null_terminated(name.encode('ascii')))

    # Payloads matching likely 'from' encodings
    candidate_froms = ["UTF-8", "US-ASCII", "ISO-8859-1", "UTF-16LE", "UTF-16BE", "UTF-16"]

    # Choose subset of texts deterministically from seed randomness
    k = min(3, len(SAMPLES_TEXT))
    chosen_texts = [rng.choice(SAMPLES_TEXT) for _ in range(6)]

    for enc in candidate_froms:
        for txt in chosen_texts:
            payload = encode_payload(txt, enc)
            pieces.append(make_null_terminated(payload))

    # Edge cases
    pieces.append(b"\x00")  # empty string
    long_ascii = ("A" * rng.randint(8, 64)).encode('ascii')
    pieces.append(make_null_terminated(long_ascii))
    lat1_mixed = "Straße München café"
    pieces.append(make_null_terminated(encode_payload(lat1_mixed, "ISO-8859-1")))
    pieces.append(make_null_terminated(lat1_mixed.encode('utf-8')))

    # UTF-16 with BOM sample
    bom_text = "with BOM ©®"
    pieces.append(make_null_terminated(bom_text.encode('utf-16')))  # includes BOM

    blob = b"".join(pieces)
    return blob[:4096]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    return build_blob(rng)

import random
import struct
import itertools

# Generator for UCS-4 (UTF-32 code points) encoded as bytes for FUZZ_PARAM_STR(),
# which the stub treats as raw bytes and widens each byte to uint32_t code points.
# Therefore, to craft valid UCS-4 input for the stubs, we must ensure each byte is
# a meaningful single-byte code point. The stub then NUL-terminates in uint32_t.
# Our goal: produce byte strings that, when each byte is interpreted as a Unicode
# code point value (0..255), form interesting IDNA labels or domain names.

ASCII = (
    [ord(c) for c in "abcdefghijklmnopqrstuvwxyz"] +
    [ord(c) for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ"] +
    [ord(c) for c in "0123456789"]
)

# Common separators and punctuation possibly relevant to IDNA/domain handling.
DOT = ord('.')
HYPHEN = ord('-')
UNDERSCORE = ord('_')
SPACE = ord(' ')
TILDE = ord('~')

# Useful label components
def alpha(r):
    return random.choice([ord('a'), ord('b'), ord('c'), ord('x'), ord('z')]) if r.random() < 0.5 else random.choice(range(ord('a'), ord('z')+1))

def digit(r):
    return random.choice(range(ord('0'), ord('9')+1))

def alnum(r):
    return r.choice(list(range(ord('a'), ord('z')+1)) + list(range(ord('0'), ord('9')+1)))

# Generate a single ASCII label obeying typical IDNA/STD3 constraints (start/end alnum, hyphens allowed internally)
def make_std3_label(r, min_len=1, max_len=20):
    n = r.randint(min_len, max_len)
    if n == 1:
        return bytes([alnum(r)])
    # start with alnum
    out = [alnum(r)]
    # middle
    for _ in range(n-2):
        out.append(r.choice([alnum(r), HYPHEN]))
    # end with alnum
    out.append(alnum(r))
    return bytes(out)

# Generate label with edge conditions: leading/trailing hyphen, double hyphen in 3rd/4th, long labels, empty label etc.
# Even if some are not strictly valid, the library should handle errors; but we also want many valid ones.
# Keep primarily valid, with occasional edge.

def make_edge_label(r):
    choice = r.randint(0, 6)
    if choice == 0:
        # ACE prefix style
        core = make_std3_label(r, 1, 10)
        return b"xn--" + core
    if choice == 1:
        # leading hyphen (often invalid under STD3)
        core = make_std3_label(r, 1, 10)
        return bytes([HYPHEN]) + core
    if choice == 2:
        # trailing hyphen (often invalid under STD3)
        core = make_std3_label(r, 1, 10)
        return core + bytes([HYPHEN])
    if choice == 3:
        # double hyphen at pos 3-4
        rest = make_std3_label(r, 3, 10)
        # ensure length >= 4
        if len(rest) < 4:
            rest = (rest + b"abcd")[:4]
        return rest[:2] + b"--" + rest[4:]
    if choice == 4:
        # numeric-only label
        n = r.randint(1, 10)
        return bytes([digit(r) for _ in range(n)])
    if choice == 5:
        # single-character label
        return bytes([alnum(r)])
    # longer label close to 63
    n = r.randint(50, 63)
    # maintain start/end alnum
    middle = [r.choice([alnum(r), HYPHEN]) for _ in range(n-2)]
    return bytes([alnum(r)]) + bytes(middle) + bytes([alnum(r)])

# Assemble domain with multiple labels

def make_domain(r):
    labels = []
    # decide number of labels: 1 to 6
    nlabels = r.randint(1, 6)
    for i in range(nlabels):
        if r.random() < 0.35:
            lab = make_edge_label(r)
        else:
            lab = make_std3_label(r)
        labels.append(lab)
    # Occasionally add empty label at end to represent trailing dot (FQDN) when widened -> '.' only => acts as separator
    trailing_dot = r.random() < 0.2
    dom = b".".join(labels)
    if trailing_dot:
        dom += b"."
    return dom

# Build inputs that exercise both A-label decoding and ordinary labels
# The stubs treat each byte as a code point, so we must keep within 0..255 bytes.
# We can include ASCII-only punycode A-labels like xn--d1acufc (пример)
ACE_SAMPLES = [
    b"xn--d1acufc",      # "пример"
    b"xn--bcher-kva",    # "bücher"
    b"xn--caf-dma",      # "café"
    b"xn--fiqs8s",       # IDN for 中国 (zhongguo)
    b"xn--wgbh1c",       # مصر
]

COMMON_TLDS = [b"com", b"net", b"org", b"edu", b"gov", b"io", b"dev", b"xn--p1ai"]

def mix_idn_domain(r):
    parts = []
    # choose pattern
    pattern = r.randint(0, 5)
    if pattern == 0:
        parts = [r.choice(ACE_SAMPLES)]
    elif pattern == 1:
        parts = [make_std3_label(r), r.choice(ACE_SAMPLES)]
    elif pattern == 2:
        parts = [r.choice(ACE_SAMPLES), make_std3_label(r)]
    elif pattern == 3:
        parts = [make_edge_label(r), r.choice(ACE_SAMPLES), make_std3_label(r)]
    elif pattern == 4:
        # multi-level
        parts = [make_std3_label(r) for _ in range(r.randint(2,4))]
        parts.insert(r.randrange(len(parts)+1), r.choice(ACE_SAMPLES))
    else:
        # plain domain
        return make_domain(r)
    # add a common TLD
    if r.random() < 0.8:
        parts.append(r.choice(COMMON_TLDS))
    dom = b".".join(parts)
    if r.random() < 0.15:
        dom += b"."
    return dom

# Ensure length per stub (<=128 bytes before widening). Also want variability.

def clamp_for_stub(b):
    if len(b) > 128:
        return b[:128]
    return b

# Primary API

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # choose between several strategies
    strat = r.randint(0, 4)
    if strat == 0:
        data = make_domain(r)
    elif strat == 1:
        data = mix_idn_domain(r)
    elif strat == 2:
        # single label ACE sample or near-ACE
        if r.random() < 0.7:
            data = r.choice(ACE_SAMPLES)
        else:
            core = make_std3_label(r, 3, 10)
            data = b"xn--" + core
    elif strat == 3:
        # Long domain close to overall 128 bytes
        parts = []
        total = 0
        while total < 120:
            lab = make_std3_label(r, 1, r.randint(5, 20))
            if parts:
                sep = 1  # '.'
            else:
                sep = 0
            if total + sep + len(lab) > 125:
                break
            if parts:
                parts.append(b".")
                total += 1
            parts.append(lab)
            total += len(lab)
        # append TLD
        tld = r.choice(COMMON_TLDS)
        if total + 1 + len(tld) <= 128:
            if parts:
                parts.append(b".")
            parts.append(tld)
        data = b"".join(parts)
    else:
        # Edgey label placements
        labels = [make_edge_label(r) for _ in range(r.randint(1,4))]
        if r.random() < 0.7:
            labels.append(r.choice(COMMON_TLDS))
        data = b".".join(labels)
        if r.random() < 0.2:
            data += b"."

    data = clamp_for_stub(data)

    # Ensure non-empty to avoid immediate NODATA in some paths
    if not data:
        data = b"a"

    # Return as bytes; the fuzzer stub will NUL-terminate in UCS-4 itself.
    return data
